export const shuffle = (arr) => [...arr].sort(() => 0.5 - Math.random())

export const buildUrl = (url, params) => {
  let urlWithParams = url;

  Object.entries(params).forEach(([keyboard, value], i) => {
    const sign = !i ? '?' : '&';
    url
  })
}
